// Test helper for QA: puts a test string on the Mac clipboard, optionally with
// a "do not save" marker type, the way a password manager does.
//
//   swiftc -o /tmp/setpb tool/set_pasteboard.swift
//   /tmp/setpb "my test text" none
//   /tmp/setpb "pretend password" org.nspasteboard.ConcealedType
//   /tmp/setpb "pretend one-time code" org.nspasteboard.TransientType
//   /tmp/setpb "pretend generated" org.nspasteboard.AutoGeneratedType
//
// Kusunga must save the first and never the other three.
import AppKit

guard CommandLine.arguments.count == 3 else {
  print("usage: setpb <text> <marker-type | none>")
  exit(2)
}
let text = CommandLine.arguments[1]
let marker = CommandLine.arguments[2]
let pasteboard = NSPasteboard.general
pasteboard.clearContents()
var types: [NSPasteboard.PasteboardType] = [.string]
if marker != "none" { types.append(NSPasteboard.PasteboardType(marker)) }
pasteboard.declareTypes(types, owner: nil)
pasteboard.setString(text, forType: .string)
if marker != "none" { pasteboard.setData(Data(), forType: NSPasteboard.PasteboardType(marker)) }
